<script setup lang="ts">
import {IconPlus,IconPaperclip,IconEdit,IconCopy,IconSend,IconHistory,IconArchive,IconCheck,IconX,IconClipboardCheck} from '@tabler/icons-vue'
import {onMounted,onUnmounted,ref,watch,computed,nextTick} from 'vue'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
import {useWorkspaceView} from '../workspace/context'
import AssignmentDetails from './AssignmentDetails.vue'
import {scheduleSummary,scheduleGroup} from './presentation'
import RewardBundleFields from './RewardBundleFields.vue'
import ScheduleFields from './ScheduleFields.vue'
type Template=components['schemas']['RitualView'];type Assignment=components['schemas']['RitualAssignmentView'];type Occurrence=components['schemas']['OccurrenceView'];type Schedule=components['schemas']['Schedule']
const props=defineProps<{target?:{id:string;nonce:number}|null;client:SessionClient;ru:boolean;me:components['schemas']['MemberView'];active:boolean;participants:components['schemas']['ParticipantView'][]}>()
const view=useWorkspaceView()
const t=(en:string,ru:string)=>props.ru?ru:en
type Evidence=components['schemas']['EvidenceView']
const rewardOptions=ref<Pick<components['schemas']['RewardView'],'version_id'|'title'>[]>([]),rewardIds=ref<string[]>([]),currencyAmount=ref(0),rewarding=ref<Assignment|null>(null),evidenceRequired=ref(false),allowedTypes=ref<string[]>(['link','photo','video'])
const evidenceLinks=ref(''),uploaded=ref<Evidence[]>([]),pendingFiles=ref<{file:File;key:string}[]>([])
const templates=ref<Template[]>([]),assignments=ref<Assignment[]>([]),occurrences=ref<Occurrence[]>([]),notices=ref<components['schemas']['RitualNoticeView'][]>([])
const modal=ref<HTMLDialogElement|null>(null)
const busy=ref(false),error=ref(''),success=ref(''),filter=ref('all'),history=ref<Template[]>([])
const creationFlow=ref(false),editor=ref(false),selected=ref<Template|null>(null),title=ref(''),description=ref('')
function today(zone:string){return new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function initial():Schedule{return {kind:'daily',timezone:props.me.timezone,hour:9,minute:0,start_date:today(props.me.timezone),weekdays:[],window_hours:24}}
const assigning=ref<Template|null>(null),rescheduling=ref<Assignment|null>(null),recipient=ref(''),reviewers=ref<string[]>([]),approval=ref(true),schedule=ref<Schedule>(initial()),assignKey=ref(crypto.randomUUID())
const reporting=ref<Occurrence|null>(null),reviewing=ref<Occurrence|null>(null),reportText=ref(''),comment=ref(''),reportKey=ref(crypto.randomUUID())
const recipients=computed(()=>props.participants.filter(p=>view.recipients('rituals.assign').includes(p.id)))
const contextOccurrences=computed(()=>occurrences.value.filter(o=>view.occurrence(o,assignments.value)))
const visibleAssignments=computed(()=>assignments.value.filter(a=>view.assignment(a)&&(currentTab.value==='mine'?a.recipient_id===props.me.id:a.issuer_id===props.me.id)))
const tab=ref<'assignments'|'review'|'mine'|'library'>('assignments')
const hasOwn=computed(()=>contextOccurrences.value.some(o=>o.recipient_id===props.me.id))
const performer=computed(()=>view.selected.value?.submissive_user_id===props.me.id||!view.selected.value&&hasOwn.value)
const currentTab=computed(()=>tab.value==='assignments'&&!recipients.value.length&&performer.value?'mine':tab.value)
watch(view.selected,r=>{detailId.value='';detailOpen.value=false;editor.value=false;assigning.value=null;rescheduling.value=null;rewarding.value=null;tab.value=r?.dominant_user_id===props.me.id||!r&&recipients.value.length?'assignments':'mine'})
const reviewHistory=ref(false)
const visible=computed(()=>contextOccurrences.value.filter(o=>(currentTab.value==='mine'?o.recipient_id===props.me.id:o.recipient_id!==props.me.id&&(reviewHistory.value||o.can_review&&o.status==='submitted'))&&(filter.value==='all'||o.status===filter.value)))
const detailId=ref(''),detailOpen=ref(false),detailDialog=ref<HTMLDialogElement|null>(null),editorDialog=ref<HTMLDialogElement|null>(null)
const wideMedia=window.matchMedia('(min-width:800px), (min-width:600px) and (min-aspect-ratio:4/5)'),expanded=ref(wideMedia.matches)
function resize(){expanded.value=wideMedia.matches}
onMounted(()=>wideMedia.addEventListener('change',resize));onUnmounted(()=>wideMedia.removeEventListener('change',resize))
const inspected=computed(()=>visibleAssignments.value.find(a=>a.id===detailId.value)??visibleAssignments.value[0]??null)
const groups=computed(()=>['daily','weekly','once'].map(kind=>({kind,rows:visibleAssignments.value.filter(a=>a.schedule.kind===kind)})).filter(g=>g.rows.length))
function inspect(a:Assignment){detailId.value=a.id;detailOpen.value=true}
watch([detailOpen,expanded,inspected],async()=>{await nextTick();if(detailOpen.value&&!expanded.value&&inspected.value){if(!detailDialog.value?.open)detailDialog.value?.showModal()}else detailDialog.value?.close()})
function closeEditor(){editor.value=false;assigning.value=null;rescheduling.value=null;rewarding.value=null}
watch([editor,assigning,rescheduling,rewarding],async()=>{await nextTick();if(editor.value||assigning.value||rescheduling.value||rewarding.value){detailOpen.value=false;detailDialog.value?.close();if(!editorDialog.value?.open)editorDialog.value?.showModal()}else editorDialog.value?.close()})
const name=(id:string)=>props.participants.find(p=>p.id===id)?.display_name??id
const time=(value:string)=>new Intl.DateTimeFormat(props.ru?'ru-RU':'en-GB',{timeZone:props.me.timezone,year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(new Date(value))
const label=(value:string)=>({scheduled:t('Scheduled','Запланировано'),submitted:t('Awaiting review','Ждёт проверки'),needs_changes:t('Changes requested','На доработке'),approved:t('Approved','Одобрено'),missed:t('Missed','Пропущено'),skipped:t('Skipped','Пропущено добровольно'),cancelled:t('Cancelled','Отменено'),draft:t('Draft','Черновик'),published:t('Published','Опубликовано'),archived:t('Archived','В архиве'),active:t('Active','Действует'),paused:t('Paused','На паузе'),revoked:t('Revoked','Отозвано'),daily:t('Daily','Ежедневно'),weekly:t('Weekly','Еженедельно'),once:t('Once','Однократно')}[value]??t('Unavailable','Недоступно'))
async function load(){templates.value=await props.client.get('/rituals');assignments.value=await props.client.get('/ritual-assignments');occurrences.value=await props.client.get('/ritual-occurrences');notices.value=await props.client.get('/ritual-notices')}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';success.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'NETWORK_ERROR'}finally{busy.value=false}}
onMounted(()=>run(load));watch(()=>props.active,active=>{if(active)void run(load)})
watch(view.revision,()=>{recipient.value='';occurrences.value=occurrences.value.map(o=>({...o,can_report:false,can_review:false}));void run(load)})
watch(()=>props.me.paused,()=>{occurrences.value=occurrences.value.map(o=>({...o,can_report:false,can_review:false}));void run(load)})
watch(recipient,id=>{reviewers.value=reviewers.value.filter(r=>r!==id)})
watch([recipient,reviewers,approval,schedule,rewardIds,currencyAmount,evidenceRequired,allowedTypes],()=>{assignKey.value=crypto.randomUUID()},{deep:true})
watch([reportText,evidenceLinks,uploaded],()=>{reportKey.value=crypto.randomUUID()})
watch([reporting,reviewing],async()=>{await nextTick();if(reporting.value||reviewing.value){if(!modal.value?.open)modal.value?.showModal()}else modal.value?.close()})
watch(()=>props.target,async target=>{if(!target)return;await run(load);const o=contextOccurrences.value.find(o=>o.id===target.id);if(!o)return;tab.value=o.recipient_id===props.me.id?'mine':'review';if(o.can_review&&!props.me.paused){comment.value='';reviewing.value=o}else if(o.can_report&&!props.me.paused){await startReport(o)}else{await nextTick();document.getElementById('occurrence-'+o.id)?.scrollIntoView({block:'center'})}})
function edit(r:Template|null){creationFlow.value=!r;if(!r)tab.value='assignments';selected.value=r;title.value=r?.title??'';description.value=r?.description??'';editor.value=true;assigning.value=null}
async function save(){await run(async()=>{let r=selected.value;const body={title:title.value,description:description.value};if(!r){r=await props.client.post<Template>('/rituals',body);selected.value=r}else if(r.status==='draft')r=await props.client.patch<Template>(`/rituals/${r.id}`,{...body,expected_version:r.revision});else r=await props.client.post<Template>(`/rituals/${r.id}/versions`,{...body,expected_version:r.revision});selected.value=r;if(creationFlow.value){r=await props.client.post<Template>(`/rituals/${r.id}/publish`,{expected_version:r.revision});selected.value=r;await startAssign(r);creationFlow.value=false}editor.value=false;await load()})}
async function templateAction(r:Template,action:string){await run(async()=>{await props.client.post(`/rituals/${r.id}/${action}`,{expected_version:r.revision});await load()})}
async function startAssign(r:Template){rewardOptions.value=await props.client.get('/rewards');rewardIds.value=[];currencyAmount.value=0;evidenceRequired.value=false;allowedTypes.value=['link','photo','video'];assigning.value=r;rescheduling.value=null;recipient.value='';reviewers.value=[];schedule.value=initial();approval.value=true;editor.value=false}
function startSchedule(a:Assignment){rescheduling.value=a;assigning.value=null;const date=new Date();date.setDate(date.getDate()+1);schedule.value={...a.schedule,start_date:new Intl.DateTimeFormat('en-CA',{timeZone:a.schedule.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}}
async function startRewards(a:Assignment){rewardOptions.value=await props.client.get('/rewards');rewardIds.value=[...(a.reward_version_ids??[])];for(const id of rewardIds.value){if(!rewardOptions.value.some(r=>r.version_id===id))rewardOptions.value.push({version_id:id,title:a.reward_titles?.[id]??t('Saved reward version','Сохранённая версия награды')})}currencyAmount.value=a.currency_amount??0;rewarding.value=a;assigning.value=null;rescheduling.value=null}
async function saveRewards(){const a=rewarding.value;if(!a)return;await run(async()=>{await props.client.put(`/ritual-assignments/${a.id}/rewards`,{expected_version:a.revision,reward_version_ids:rewardIds.value,currency_amount:currencyAmount.value});rewarding.value=null;await load()})}
async function assign(){await run(async()=>{const r=assigning.value;if(!r)return;await props.client.post(`/rituals/${r.id}/assignments`,{recipient_id:recipient.value,reviewer_ids:reviewers.value.filter(id=>id!==recipient.value),approval_required:approval.value,evidence_policy:{required:evidenceRequired.value,allowed_types:allowedTypes.value},reward_version_ids:rewardIds.value,currency_amount:currencyAmount.value,schedule:schedule.value,idempotency_key:assignKey.value});assigning.value=null;await load();success.value=t('Assignment created','Назначение создано')})}
async function saveSchedule(){await run(async()=>{const a=rescheduling.value;if(!a)return;await props.client.put(`/ritual-assignments/${a.id}/schedule`,{expected_version:a.revision,schedule:schedule.value});rescheduling.value=null;await load()})}
async function assignmentAction(a:Assignment,action:string){await run(async()=>{await props.client.post(`/ritual-assignments/${a.id}/${action}`,{expected_version:a.revision});await load()})}
async function startReport(o:Occurrence){await run(async()=>{const files=await props.client.get<Evidence[]>(`/ritual-occurrences/${o.id}/evidence`);reportText.value='';evidenceLinks.value='';uploaded.value=files;pendingFiles.value=[];reportKey.value=crypto.randomUUID();reviewing.value=null;reporting.value=o})}
async function submit(){await run(async()=>{const o=reporting.value;if(!o)return;await props.client.post(`/ritual-occurrences/${o.id}/report`,{expected_version:o.revision,idempotency_key:reportKey.value,text:reportText.value,links:evidenceLinks.value.split(/\n/).map(s=>s.trim()).filter(Boolean),evidence_ids:uploaded.value.map(e=>e.id)});reporting.value=null;await load()})}
async function review(decision:'approved'|'needs_changes'){await run(async()=>{const o=reviewing.value;if(!o)return;await props.client.post(`/ritual-occurrences/${o.id}/review`,{expected_version:o.revision,decision,comment:comment.value});reviewing.value=null;reviewHistory.value=true;await load()})}
async function skip(o:Occurrence){await run(async()=>{await props.client.post(`/ritual-occurrences/${o.id}/skip`,{expected_version:o.revision});await load()})}
const historyOpen=ref(false),historyTitle=ref(''),historyDialog=ref<HTMLDialogElement|null>(null)
function closeHistory(){historyOpen.value=false;history.value=[]}
watch(historyOpen,async open=>{await nextTick();if(open)historyDialog.value?.showModal();else historyDialog.value?.close()})
watch(view.selected,closeHistory)
async function versionHistory(r:Template){await run(async()=>{history.value=await props.client.get(`/rituals/${r.id}/versions`);historyTitle.value=r.title;historyOpen.value=true})}

async function chooseFiles(event:Event){pendingFiles.value=Array.from((event.target as HTMLInputElement).files??[]).map(file=>({file,key:crypto.randomUUID()}));await uploadFiles()}
async function uploadFiles(){await run(async()=>{const o=reporting.value;if(!o)return;for(const item of [...pendingFiles.value]){if(item.file.size>8*1024*1024)throw new Error(t('Maximum file size is 8 MiB','Максимальный размер файла — 8 МиБ'));const bytes=new Uint8Array(await item.file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const e=await props.client.post<Evidence>(`/ritual-occurrences/${o.id}/evidence`,{idempotency_key:item.key,kind:item.file.type.startsWith('image/')?'photo':'video',media_type:item.file.type,data_base64:btoa(raw)});uploaded.value.push(e);pendingFiles.value=pendingFiles.value.filter(p=>p!==item)}})}
async function discardEvidence(e:Evidence){await run(async()=>{await props.client.delete(`/ritual-evidence/${e.id}`);uploaded.value=uploaded.value.filter(p=>p.id!==e.id)})}
async function downloadEvidence(e:Evidence){await run(async()=>{const data=await props.client.get<components['schemas']['EvidenceDownload']>(`/ritual-evidence/${e.id}`);const bytes=Uint8Array.from(atob(data.data_base64),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'}));const a=document.createElement('a');a.href=url;a.download=`evidence-${e.id}.${({'image/png':'png','image/jpeg':'jpg','video/mp4':'mp4','video/webm':'webm'} as Record<string,string>)[e.media_type]??'bin'}`;a.click();URL.revokeObjectURL(url)})}
const enoughEvidence=computed(()=>!reporting.value?.evidence_policy?.required||uploaded.value.length>0||evidenceLinks.value.trim().length>0)
const allowed=(o:Occurrence,kind:string)=>o.evidence_policy?.allowed_types?.includes(kind as 'link'|'photo'|'video')??true
</script>
<template>
 <section id="rituals" class="ritual-workspace" aria-labelledby="rituals-title">
  <h2 id="rituals-title" class="sr-only">{{t('Rituals','Ритуалы')}}</h2>

  <div class="ritual-controls"><nav class="ritual-tabs" :aria-label="t('Ritual views','Представления ритуалов')"><button v-if="recipients.length" :aria-pressed="currentTab==='assignments'" @click="tab='assignments'">{{t('Assigned rituals','Ритуалы')}}</button><button :aria-pressed="currentTab==='review'" @click="tab='review'">{{t('Review queue','Проверка')}} · {{contextOccurrences.filter(o=>o.can_review).length}}</button><button v-if="performer" :aria-pressed="currentTab==='mine'" @click="tab='mine'">{{t('My executions','Мои выполнения')}}</button><button v-if="recipients.length" :aria-pressed="currentTab==='library'" @click="tab='library'">{{t('Templates','Шаблоны')}}</button></nav><button v-if="recipients.length" class="ritual-create" :disabled="busy||me.paused" :aria-label="t('New ritual','Новый ритуал')" :title="t('New ritual','Новый ритуал')" @click="edit(null)"><IconPlus :size="19" :stroke-width="1.5" /><span>{{t('New ritual','Новый ритуал')}}</span></button></div>
  <p v-if="busy" role="status">{{t('Loading rituals…','Загружаем ритуалы…')}}</p><p v-if="error" role="alert">{{error}} · {{t('Refresh to load the current state.','Обновите данные для актуального состояния.')}}</p><p v-if="success" role="status">{{success}}</p>
  <div v-if="currentTab==='review'||currentTab==='mine'" class="ritual-columns ritual-view-enter" :class="{'ritual-review':currentTab==='review'}" :key="currentTab"><div>
   <div class="section-heading"><h3>{{currentTab==='mine'?t('My executions','Мои выполнения'):t('Review queue','Проверка выполнения')}}</h3><details v-if="currentTab==='mine'||reviewHistory" class="ritual-status-filter"><summary>{{t('Status','Статус')}}: {{filter==='all'?t('All','Все'):label(filter)}}</summary><div><button v-for="status in ['all','scheduled','submitted','needs_changes','approved','missed','skipped','cancelled']" :key="status" :aria-pressed="filter===status" @click="filter=status;($event.currentTarget as HTMLElement).closest('details')?.removeAttribute('open')">{{status==='all'?t('All','Все'):label(status)}}</button></div></details><button v-if="currentTab==='review'" class="quiet-button" :aria-pressed="reviewHistory" @click="reviewHistory=!reviewHistory">{{reviewHistory?t('Back to pending reports','К ожидающим отчётам'):t('Review history','История проверок')}}</button></div><p v-if="!visible.length" class="empty-state">{{currentTab==='review'?t('No reports awaiting review.','Нет отчётов для проверки.'):t('No visible executions.','Нет доступных выполнений.')}}</p>
   <div class="occurrence-list"><article v-for="o in visible" :key="o.id" class="occurrence-row" :id="'occurrence-'+o.id">
    <template v-if="currentTab==='review'">
     <span class="review-avatar person-monogram" aria-hidden="true">{{name(o.recipient_id).slice(0,1)}}</span>
     <div class="compact-review-body"><div class="compact-review-title"><h4>{{o.title}}</h4><span class="status-tag" :data-status="o.status">{{label(o.status)}}</span></div>
      <p v-if="o.reports.length" class="report-preview">{{o.reports.at(-1)?.text}}</p>
      <div class="review-metadata"><span>{{name(o.recipient_id)}}</span><span v-if="o.reports.length">{{time(o.reports.at(-1)!.submitted_at)}}</span><span v-if="o.reports.at(-1)?.links?.length||o.reports.at(-1)?.attachments?.length"><IconPaperclip :size="14" />{{t('Evidence','Доказательства')}} · {{(o.reports.at(-1)?.links?.length??0)+(o.reports.at(-1)?.attachments?.length??0)}}</span></div>
     </div>
     <button v-if="o.reports.length" class="compact-review-action" :aria-label="o.can_review?t('Review report','Проверить отчёт'):t('Report history','История отчётов')+' · '+o.reports.length" :title="o.can_review?t('Review report','Проверить отчёт'):t('Report history','История отчётов')+' · '+o.reports.length" :disabled="busy" @click="reviewing=o;comment='';reporting=null"><component :is="o.can_review?IconClipboardCheck:IconHistory" :size="19" :stroke-width="1.5" /></button>
    </template><template v-else>
    <div class="occurrence-heading"><div><h4>{{o.title}}</h4><p class="muted">{{name(o.recipient_id)}} · <time :datetime="o.due_at">{{time(o.due_at)}}</time></p></div><span class="status-tag" :data-status="o.status">{{label(o.status)}}</span></div>
    <p v-if="currentTab==='mine'">{{o.description}}</p><p class="muted">{{t('Report until','Отчёт до')}} {{time(o.expires_at)}}</p>
    <details v-if="o.reports.length"><summary>{{t('Report history','История отчётов')}} · {{o.reports.length}}</summary><div v-for="r in o.reports" :key="r.id" class="report-attempt"><p class="muted">{{t('Attempt','Попытка')}} {{r.attempt}} · {{time(r.submitted_at)}}</p><p>{{r.text}}</p><p v-for="link in r.links" :key="link"><a :href="link" target="_blank" rel="noopener noreferrer">{{t('Open evidence link · external site','Открыть доказательство · внешний сайт')}}</a></p><button v-for="e in r.attachments" :key="e.id" class="secondary" :disabled="busy" @click="downloadEvidence(e)">{{e.kind==='photo'?t('Download photo evidence','Скачать фото-доказательство'):t('Download video evidence','Скачать видео-доказательство')}}</button><p v-if="r.decision">{{label(r.decision)}} · {{r.reviewer_id?name(r.reviewer_id):''}}</p><p v-if="r.comment">{{r.comment}}</p></div></details>
    <button v-if="o.can_report&&!me.paused" :disabled="busy" @click="startReport(o)">{{t('Write report','Написать отчёт')}}</button>
    <button v-if="o.can_review&&!me.paused" :disabled="busy" @click="reviewing=o;comment='';reporting=null">{{t('Review report','Проверить отчёт')}}</button>
    <button v-if="o.recipient_id===me.id&&['scheduled','needs_changes'].includes(o.status)" class="secondary" :disabled="busy" @click="skip(o)">{{t('Skip occurrence','Пропустить выполнение')}}</button>
    </template>
   </article></div>
  </div></div>
  <div v-if="recipients.length&&currentTab==='library'" class="ritual-library ritual-view-enter">
   <header class="template-library-heading"><h3>{{t('Templates and drafts','Шаблоны и черновики')}}</h3><span>{{templates.length}}</span></header>
   <p v-if="!templates.length" class="muted">{{t('Your authored templates will appear here.','Здесь появятся созданные вами шаблоны.')}}</p>
   <div class="ritual-template-grid"><article v-for="r in templates" :key="r.id" class="ritual-template-card">
    <header><h4>{{r.title}}</h4><span class="status-tag" :data-status="r.status">{{label(r.status)}}</span></header><p class="template-description">{{r.description}}</p>
    <div class="template-actions">
     <button :aria-label="r.status==='draft'?t('Edit ritual draft','Изменить черновик ритуала'):t('New ritual version','Новая версия ритуала')" :title="r.status==='draft'?t('Edit ritual draft','Изменить черновик ритуала'):t('New ritual version','Новая версия ритуала')" :disabled="busy||me.paused" @click="edit(r)"><component :is="r.status==='draft'?IconEdit:IconCopy" :size="18" :stroke-width="1.5" /></button>
     <button v-if="r.status==='draft'" :aria-label="t('Publish ritual','Опубликовать ритуал')" :title="t('Publish ritual','Опубликовать ритуал')" :disabled="busy||me.paused" @click="templateAction(r,'publish')"><IconCheck :size="18" :stroke-width="1.5" /></button>
     <button v-if="r.status==='published'&&recipients.length" :aria-label="t('Assign ritual','Назначить ритуал')" :title="t('Assign ritual','Назначить ритуал')" :disabled="busy||me.paused" @click="startAssign(r)"><IconSend :size="18" :stroke-width="1.5" /></button>
     <button :aria-label="t('Ritual version history','История версий ритуала')" :title="t('Ritual version history','История версий ритуала')" :disabled="busy" @click="versionHistory(r)"><IconHistory :size="18" :stroke-width="1.5" /></button>
     <button v-if="r.status!=='archived'" :aria-label="t('Archive ritual','Архивировать ритуал')" :title="t('Archive ritual','Архивировать ритуал')" :disabled="busy" @click="templateAction(r,'archive')"><IconArchive :size="18" :stroke-width="1.5" /></button>
    </div>
   </article></div>
  </div>
  <dialog ref="historyDialog" class="ritual-history-dialog" :aria-label="t('Version history','История версий')" @cancel="closeHistory"><header><div><h3>{{t('Version history','История версий')}}</h3><p>{{historyTitle}}</p></div><button class="icon-button" :aria-label="t('Close history','Закрыть историю')" :title="t('Close history','Закрыть историю')" @click="closeHistory"><IconX :size="20" /></button></header><article v-for="v in history" :key="v.version_id"><header><h4>{{v.title}}</h4><span class="status-tag" :data-status="v.status">{{label(v.status)}}</span></header><p>{{v.description}}</p></article><p v-if="!history.length" class="muted">{{t('No versions available.','Нет доступных версий.')}}</p></dialog>
  <div v-if="currentTab==='assignments'" class="ritual-browser ritual-view-enter">
   <div class="ritual-list"><p v-if="!visibleAssignments.length" class="muted">{{t('No assigned rituals in this context.','В этих отношениях пока нет назначенных ритуалов.')}}</p><div v-for="group in groups" :key="group.kind" class="ritual-group"><h3>{{scheduleGroup(group.kind,ru)}}</h3><button v-for="a in group.rows" :key="a.id" class="ritual-card" :aria-pressed="inspected?.id===a.id" @click="inspect(a)"><strong>{{a.title}}</strong><span>{{scheduleSummary(a.schedule,ru)}} · {{name(a.recipient_id)}}</span><small>{{a.approval_required?t('Review required','Проверка обязательна'):t('Without review','Без проверки')}} · {{label(a.status)}}</small></button></div></div>
   <aside v-if="expanded&&inspected" class="ritual-inspector"><AssignmentDetails :assignment="inspected" :member-id="me.id" :recipient="name(inspected.recipient_id)" :ru="ru" :busy="busy" :paused="me.paused" @schedule="startSchedule" @rewards="startRewards" @transition="assignmentAction" /></aside>
  </div>
  <dialog ref="detailDialog" class="assignment-dialog" :aria-label="t('Ritual settings','Настройки ритуала')" @cancel="detailOpen=false"><button class="quiet-button" @click="detailOpen=false">{{t('Back to rituals','К ритуалам')}}</button><AssignmentDetails v-if="!expanded&&inspected" :assignment="inspected" :member-id="me.id" :recipient="name(inspected.recipient_id)" :ru="ru" :busy="busy" :paused="me.paused" @schedule="startSchedule" @rewards="startRewards" @transition="assignmentAction" /></dialog>
  <dialog ref="editorDialog" class="ritual-edit-dialog" :aria-label="t('Ritual editor','Редактор ритуала')" @cancel="busy?$event.preventDefault():closeEditor()"><button class="quiet-button" :disabled="busy" @click="closeEditor">{{t('Close editor','Закрыть редактор')}}</button>
  <form v-if="editor" class="ritual-editor" @submit.prevent="save"><h3>{{selected?t('Ritual version','Версия ритуала'):t('Create a ritual','Создать ритуал')}}</h3><label>{{t('Ritual title','Название ритуала')}}<input v-model="title" maxlength="200" required></label><label>{{t('Ritual description','Описание ритуала')}}<textarea v-model="description" maxlength="10000" rows="4" required /></label><button :disabled="busy||me.paused">{{creationFlow?t('Next: schedule','Далее: расписание'):t('Save ritual','Сохранить ритуал')}}</button><button type="button" class="secondary" :disabled="busy" @click="editor=false">{{t('Cancel','Отмена')}}</button></form>
  <form v-if="assigning||rescheduling" class="ritual-editor" @submit.prevent="rescheduling?saveSchedule():assign()"><h3>{{assigning?.title??rescheduling?.title}}</h3><template v-if="assigning"><label>{{t('Ritual recipient','Адресат ритуала')}}<select v-model="recipient" required><option value="" disabled>—</option><option v-for="p in recipients" :key="p.id" :value="p.id">{{p.display_name}}</option></select></label><fieldset><legend>{{t('Explicit reviewers','Назначенные проверяющие')}}</legend><label v-for="p in participants.filter(p=>p.id!==recipient)" :key="p.id"><input v-model="reviewers" type="checkbox" :value="p.id">{{t('Reviewer: ','Проверяющий: ')}}{{p.display_name}}</label></fieldset><label><input v-model="approval" type="checkbox">{{t('Approval required','Требуется проверка')}}</label></template><template v-if="assigning"><fieldset><legend>{{t('Execution evidence','Доказательство выполнения')}}</legend><label><input v-model="evidenceRequired" type="checkbox">{{t('Evidence required','Доказательство обязательно')}}</label><label v-for="kind in ['link','photo','video']" :key="kind"><input v-model="allowedTypes" type="checkbox" :value="kind">{{kind==='link'?t('Link','Ссылка'):kind==='photo'?t('Photo','Фото'):t('Video','Видео')}}</label></fieldset><RewardBundleFields v-model:rewards="rewardIds" v-model:currency="currencyAmount" :options="rewardOptions" :ru="ru" /></template><ScheduleFields v-model="schedule" :ru="ru" :fixed-zone="!!rescheduling" /><p v-if="rescheduling" class="muted">{{t('Changes begin tomorrow or later. Timezone changes require a new assignment.','Изменения — со следующего дня. Для смены часового пояса нужно новое назначение.')}}</p><button :disabled="busy||me.paused||(!!assigning&&approval&&!reviewers.length)">{{rescheduling?t('Save schedule','Сохранить расписание'):t('Create ritual assignment','Создать назначение ритуала')}}</button><button type="button" class="secondary" @click="assigning=null;rescheduling=null">{{t('Cancel','Отмена')}}</button></form>
  <form v-if="rewarding" @submit.prevent="saveRewards"><h3>{{rewarding.title}}</h3><RewardBundleFields v-model:rewards="rewardIds" v-model:currency="currencyAmount" :options="rewardOptions" :ru="ru" /><p class="muted">{{t('Changes apply to future occurrences only.','Изменения действуют только для будущих выполнений.')}}</p><button :disabled="busy">{{t('Save ritual rewards','Сохранить награды ритуала')}}</button><button type="button" @click="rewarding=null">{{t('Cancel','Отмена')}}</button></form>
  </dialog>
  <dialog ref="modal" @cancel="busy?$event.preventDefault():(reporting=null,reviewing=null)" aria-modal="true" :aria-label="reporting?t('Ritual report','Отчёт ритуала'):t('Review ritual report','Проверка отчёта ритуала')" class="ritual-dialog"><template v-if="reporting||reviewing"><h3>{{(reporting??reviewing)?.title}}</h3><form v-if="reporting" @submit.prevent="submit"><label>{{t('Ritual report','Отчёт ритуала')}}<textarea v-model="reportText" maxlength="10000" rows="6" required /></label><label v-if="reporting&&allowed(reporting,'link')">{{t('Evidence links · HTTPS, one per line','Ссылки-доказательства · HTTPS, по одной на строку')}}<textarea v-model="evidenceLinks" maxlength="6146" rows="3" /></label><label v-if="reporting&&(allowed(reporting,'photo')||allowed(reporting,'video'))">{{t('Photo or video evidence','Фото или видео-доказательство')}}<input type="file" :accept="[...(allowed(reporting,'photo')?['image/jpeg','image/png']:[]),...(allowed(reporting,'video')?['video/mp4','video/webm']:[])].join(',')" :disabled="busy" @change="chooseFiles"></label><p class="muted">{{reporting.evidence_policy?.required?t('Evidence required','Доказательство обязательно'):t('Evidence optional','Доказательство необязательно')}} · {{t('Up to 3 items, 8 MiB per file. Original files may contain metadata.','До 3 доказательств, 8 МиБ на файл. Исходные файлы могут содержать метаданные.')}}</p><p v-for="e in uploaded" :key="e.id">{{e.kind==='photo'?t('Photo','Фото'):t('Video','Видео')}} · {{e.media_type}} <button type="button" :disabled="busy" @click="discardEvidence(e)">{{t('Remove evidence','Удалить доказательство')}}</button></p><button v-if="pendingFiles.length" type="button" :disabled="busy" @click="uploadFiles">{{t('Retry evidence upload','Повторить загрузку доказательства')}}</button><button :disabled="busy||me.paused||!enoughEvidence||pendingFiles.length>0">{{t('Submit report','Отправить отчёт')}}</button></form><template v-if="reviewing"><div class="review-full-history"><div v-for="r in reviewing.reports" :key="r.id" class="report-attempt"><p class="muted">{{t('Attempt','Попытка')}} {{r.attempt}} · {{time(r.submitted_at)}}</p><p>{{r.text}}</p><p v-for="link in r.links" :key="link"><a :href="link" target="_blank" rel="noopener noreferrer">{{t('Open evidence link · external site','Открыть доказательство · внешний сайт')}}</a></p><button v-for="e in r.attachments" :key="e.id" :disabled="busy" @click="downloadEvidence(e)">{{e.kind==='photo'?t('Download photo evidence','Скачать фото-доказательство'):t('Download video evidence','Скачать видео-доказательство')}}</button><p v-if="r.decision">{{label(r.decision)}} · {{r.reviewer_id?name(r.reviewer_id):''}}</p><p v-if="r.comment">{{r.comment}}</p></div></div><template v-if="reviewing.can_review&&!me.paused"><label>{{t('Review comment','Комментарий проверяющего')}}<textarea v-model="comment" rows="3" maxlength="10000" /></label><button :disabled="busy" @click="review('approved')">{{t('Approve report','Одобрить отчёт')}}</button><button :disabled="busy" class="secondary" @click="review('needs_changes')">{{t('Request changes','Вернуть на доработку')}}</button></template></template><button :disabled="busy" class="secondary" @click="reporting=null;reviewing=null">{{t('Cancel','Отмена')}}</button><p v-if="error" role="alert">{{error}}</p></template></dialog>
 </section>
</template>
